    accentPop.innerHTML = products.map(p => '<button type="button" role="menuitemradio" aria-checked="false" data-accent="' + (p.kind === "base" ? "" : p.key) + '"><i style="background:' + swatch(p) + '"></i>' + p.name + "</button>").join("");
