  /* 홈(index) B4 — 글꼴이 준비되면 들어오기 시작(.go, data-hm 이 있을 때만 — head 스크립트가 줄인 모션이 아닐 때 붙임),
     스크롤 패럴랙스는 루트에 --hm-sy(스크롤 px, 화면 높이의 1.2배까지). 미리보기 셸에서도 같은 핸들러가 지금 화면의 .hm 을 본다 */
  const hm = document.querySelector(".hm");
