  /* File Upload 예제 — 서버 대신 0.8초에 걸쳐 진행한다. data-demo-fail 은 첫 전송 실패를 보여 주는 문서 전용 표시 */
  const uploadDemo = (h, id, retried) => { let p = 0; const fail = h.hasAttribute("data-demo-fail") && !retried, t = setInterval(() => { p += 20; if (!h.querySelector('.upload-item[data-id="' + id + '"]')) return clearInterval(t); if (fail && p >= 60) { clearInterval(t); return window.DS.upload.fail(h, id); } if (p >= 100) { clearInterval(t); return window.DS.upload.done(h, id); } window.DS.upload.progress(h, id, p); }, 160); };
  document.addEventListener("ds:upload", e => { if (e.target.closest(".example-preview") && e.target.hasAttribute("data-demo")) e.detail.files.forEach(f => uploadDemo(e.target, f.id)); });
  document.addEventListener("ds:upload-retry", e => { if (e.target.closest(".example-preview") && e.target.hasAttribute("data-demo")) uploadDemo(e.target, e.detail.id, true); });
  /* Switch 예제 — 서버 대신 0.9초 뒤 응답한다. data-demo-fail 은 실패를 보여 주는 문서 전용 표시 */
  document.addEventListener("ds:switch", e => { if (!e.target.closest(".example-preview")) return; setTimeout(() => e.target.closest("[data-demo-fail]") ? e.detail.reject("정책 서버에 연결하지 못했습니다. 잠시 후 다시 시도하세요.") : e.detail.resolve(), 900); });
  /* Steps 마법사 완료 처리 중(data-async) — 서버 대신 0.9초 뒤 응답한다 */
  document.addEventListener("ds:step-finish", e => { if (!e.target.closest(".example-preview") || !e.detail.resolve) return; setTimeout(() => e.detail.resolve(), 900); });
  /* Tree 펼칠 때 불러오기 — 문서 예제의 응답을 흉내 낸다(조회는 제품 몫). data-demo-fail 항목은 실패 */
  document.addEventListener("ds:tree-load", e => { if (!e.target.closest(".example-preview")) return; setTimeout(() => e.target.closest("[data-demo-fail]") ? e.detail.reject() : e.detail.resolve([{ label: "WEB-01", value: e.detail.value + "-web" }, { label: "DB-01", value: e.detail.value + "-db" }]), 800); });
  /* Notification Center — 더 보기 응답과 새 알림 도착을 흉내 낸다(받아 오는 연결은 제품 몫). data-demo-fail 은 첫 더 보기 실패 */
  document.addEventListener("ds:notify-more", e => { const h = e.target; if (!h.closest(".example-preview")) return; setTimeout(() => { if (h.hasAttribute("data-demo-fail") && !h._demoTried) { h._demoTried = true; return e.detail.reject(); } e.detail.resolve([{ id: "old-1", group: "이전", severity: "low", title: "USB 저장장치 사용이 기록되었습니다", sub: "PC-1188 · 이운영", time: "11월 10일", datetime: "2026-11-10T16:20", unread: false }, { id: "old-2", group: "이전", title: "에이전트 2.4.1 배포가 끝났습니다", sub: "전체 1,284대", time: "11월 9일", datetime: "2026-11-09T11:05", unread: false }], { done: true }); }, 800); });
  let demoN = 0;
  document.addEventListener("click", e => { const b = e.target.closest("[data-demo-notify]"); if (!b || !b.closest(".example-preview")) return; const h = document.getElementById(b.getAttribute("data-demo-notify")); if (h) window.DS.notify.add(h, { id: "live-" + (++demoN), severity: "critical", title: "관리자 계정 로그인이 5회 실패했습니다", sub: "admin · 203.0.113.24", time: "방금", datetime: new Date().toISOString() }); });
  document.addEventListener("click", e => { if (!e.target.closest(".hmenu,.drawer,.copy-helper")) closeAll(); if (!e.target.closest(".val-cell,.icon-tile,#valPop,.copy-helper")) closeValPop(); });
  document.addEventListener("focusin", e => { if (!e.target.closest(".hmenu,.drawer,.copy-helper")) closeAll(); if (!e.target.closest(".val-cell,.icon-tile,#valPop,.copy-helper")) closeValPop(); });
